-function groupByDate(items: Appointment[]): [string, Appointment[]][] {
-  const grouped = new Map<string, Appointment[]>();
-  [...items]
-    .sort(compareAppointments)
-    .forEach((item) =>
-      grouped.set(item.date, [...(grouped.get(item.date) ?? []), item]),
-    );
-  return Array.from(grouped);
-}
